INSERT INTO patient_longitudinal_records (patient_id, hn, period_offset, systolic, diastolic, pulse, respiratory_rate, hba1c, c_peptide, lipid_ldl, med_metformin, med_insulin, med_arb, med_ccb, med_acei) SELECT p.id, 'HT0014', 5, 118, 81, 115, 19, NULL, NULL, NULL, 0, 0, 0, 1, 0 FROM patients p WHERE p.hn='HT0014' AND NOT EXISTS (SELECT 1 FROM patient_longitudinal_records r WHERE r.hn='HT0014' AND r.period_offset=5);
